</main></div></div><script nonce="<?= htmlspecialchars(\App\Core\Security::nonce(),ENT_QUOTES,'UTF-8') ?>">(()=>{const b=document.querySelector('.menu-button'),o=document.querySelector('[data-close-menu]'),s=document.getElementById('admin-sidebar');if(b&&s){const set=v=>{document.body.classList.toggle('nav-open',v);b.setAttribute('aria-expanded',v?'true':'false');b.setAttribute('aria-label',v?'Chiudi menu':'Apri menu')};b.addEventListener('click',()=>set(!document.body.classList.contains('nav-open')));o?.addEventListener('click',()=>set(false));s.addEventListener('click',e=>{if(e.target.closest('a')&&matchMedia('(max-width:980px)').matches)set(false)});document.addEventListener('keydown',e=>{if(e.key==='Escape')set(false)})}const legacy=/return\s+confirm\((['"])(.*?)\1\)\s*;?/;document.querySelectorAll('[onsubmit],[onclick]').forEach(el=>{const raw=el.getAttribute('onsubmit')||el.getAttribute('onclick')||'',match=raw.match(legacy);if(!match)return;el.dataset.confirm=match[2];el.removeAttribute('onsubmit');el.removeAttribute('onclick')});document.addEventListener('submit',e=>{const message=e.target.dataset.confirm;if(message&&!confirm(message))e.preventDefault()},true);document.addEventListener('click',e=>{const target=e.target.closest('[data-confirm]');if(target&&target.tagName!=='FORM'&&!confirm(target.dataset.confirm))e.preventDefault()},true);const groups={action:['','azioni','gestione'],compact:['id','#','n.','numero','anno','revisione','iscrizioni'],date:['data','data e ora','data fattura','data ricevuta','creato il','aggiornato il'],status:['stato','verifica','pubblicato','presenza','attestato'],primary:['titolo','evento','oggetto','cliente','nome','partecipante','file','prodotto / modello','modello']};document.querySelectorAll('main table').forEach(table=>{table.classList.add('admin-data-table');const headers=[...table.querySelectorAll('thead th')];headers.forEach((th,index)=>{const label=th.textContent.replace(/[↕▲▼]/g,'').replace(/\s+/g,' ').trim().toLowerCase();let type=Object.keys(groups).find(key=>groups[key].includes(label));if(!type&&index===headers.length-1)type='action';if(!type)return;const className='col-'+type;th.classList.add(className);table.querySelectorAll('tbody tr').forEach(row=>{const cell=row.children[index];if(cell&&!cell.hasAttribute('colspan'))cell.classList.add(className)})})});})();</script></body></html>
